// analyzeLibraryFile keeps fanal's analysis scoped to one in-memory lockfile.
func analyzeLibraryFile(path string, content []byte) ([]models.LibraryScanner, error) {
	apps, err := analyzer.GetLibraries(extractor.FileMap{path: content})
	if err != nil {
		return nil, err
	}
	return convertLibWithScanner(apps)
}

func convertLibWithScanner(apps []types.Application) ([]models.LibraryScanner, error) {
	scanners := []models.LibraryScanner{}
	for _, app := range apps {
		libs := []trivyTypes.Library{}
		for _, lib := range app.Libraries {
			libs = append(libs, trivyTypes.Library{
				Name:    lib.Library.Name,
				Version: lib.Library.Version,
			})
		}
		scanners = append(scanners, models.LibraryScanner{
			Path: app.FilePath,
			Libs: libs,
		})
	}
	return scanners, nil
